const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  await ee.data.authenticateViaPrivateKey(privateKey);
  await ee.initialize();

  // 1. Geometry & Time Definitions
  const countryName = 'Namibia';
  const geometry = ee.FeatureCollection("FAO/GAUL/2015/level0")
    .filter(ee.Filter.eq('ADM0_NAME', countryName))
    .first()
    .geometry();

  const startYearLTA = 2003;
  const endYearLTA = 2017;
  const monthLTA = 2; // February

  const start2019 = '2019-02-21';
  const end2019 = '2019-02-28';

  // MODIS MOD13Q1 V6 provides 16-day NDVI at 250m resolution.
  const collection = ee.ImageCollection('MODIS/051/MOD13Q1');

  // Function to mask poor quality pixels
  function maskModisNdvi(image) {
    const pixelReliability = image.select('250m_16_days_pixel_reliability');
    // Pixel reliability values:
    // 0: Good data
    // 1: Marginal data (use with caution)
    // 2: Snow/Ice
    // 3: Cloudy
    const goodQuality = pixelReliability.eq(0).or(pixelReliability.eq(1));
    return image.updateMask(goodQuality).select('250m_16_days_NDVI');
  }

  // 2. Data Acquisition & Check for 2019
  // MODIS 16-day composites are named by the start date of the 16-day period.
  // To cover Feb 21-28, 2019, we need composites whose 16-day window includes this date range.
  // For example, a composite starting around Feb 10th or Feb 18th would cover it.
  // We'll filter for images whose start date is within February 2019.
  let collection2019 = collection
    .filterDate('2019-02-01', '2019-02-28') // Filter for February 2019
    .map(maskModisNdvi)
    .mean() // Take the mean of available images in Feb 2019
    .clip(geometry);

  const size2019 = (await ee.ImageCollection([collection2019]).size().getInfo());

  if (size2019 === 0) {
    console.log("No MODIS data found for February 2019.");
    console.log("C1");
    return;
  }

  // 3. Data Acquisition & Check for Long-Term Average (LTA)
  let ltaImages = ee.ImageCollection([]);
  for (let year = startYearLTA; year <= endYearLTA; year++) {
    const startDate = ee.Date.fromYMD(year, monthLTA, 1);
    const endDate = ee.Date.fromYMD(year, monthLTA, 28); // February has 28 or 29 days

    const yearCollection = collection
      .filterDate(startDate, endDate)
      .map(maskModisNdvi);

    const yearCollectionSize = await yearCollection.size().getInfo();
    if (yearCollectionSize > 0) {
        ltaImages = ltaImages.merge(yearCollection.mean());
    } else {
        console.log(`Warning: No MODIS data for February ${year}.`);
    }
  }

  if (ltaImages.size().getInfo() === 0) {
    console.log("No MODIS data found for LTA period (2003-2017 February).");
    console.log("C1");
    return;
  }

  const ltaNDVI = ltaImages.mean().clip(geometry);

  // 4. Processing and Calculation
  // Scale for reduceRegion (using 1000m for national average)
  const scale = 1000;

  // Calculate mean NDVI for 2019
  const regionStats2019 = await collection2019.reduceRegion({
    reducer: ee.Reducer.mean().setOutputs(['NDVI']),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const ndvi2019 = regionStats2019.NDVI;

  // Calculate mean NDVI for LTA
  const regionStatsLTA = await ltaNDVI.reduceRegion({
    reducer: ee.Reducer.mean().setOutputs(['NDVI']),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const ndviLTA = regionStatsLTA.NDVI;

  // Validate results
  if (ndvi2019 === null || isNaN(ndvi2019) || ndviLTA === null || isNaN(ndviLTA)) {
    console.log("Calculation failed: One or both NDVI values are null/NaN.");
    console.log(`2019 NDVI: ${ndvi2019}, LTA NDVI: ${ndviLTA}`);
    console.log("C3");
    return;
  }

  // Get pixel counts for validation
  const count2019 = await collection2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const countLTA = await ltaNDVI.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (count2019 === 0) {
    console.log("No valid pixels for 2019 after masking and clipping.");
    console.log("C2");
    return;
  }

  if (countLTA === 0) {
    console.log("No valid pixels for LTA after masking and clipping.");
    console.log("C2");
    return;
  }

  // MODIS NDVI values range from -2000 to 10000, scaled by 10000.
  const scaledNdvi2019 = ndvi2019 / 10000;
  const scaledNdviLTA = ndviLTA / 10000;

  // 5. Validation & Final Answer
  console.log(`2019 February NDVI (mean): ${scaledNdvi2019.toFixed(3)} (Pixels: ${count2019})`);
  console.log(`LTA February NDVI (mean): ${scaledNdviLTA.toFixed(3)} (Pixels: ${countLTA})`);

  // "Worse" means lower NDVI
  if (scaledNdvi2019 < scaledNdviLTA) {
    console.log("A");
  } else {
    console.log("B");
  }
}

runAnalysis().catch(err => {
  console.error("Error running analysis:", err);
  console.log("D"); // Indicate a general error or execution issue
});
